const e=$json.execution||{};
const w=$json.workflow||{};
const message=String(e.error?.message||$json.error?.message||'Unknown error');
let category='WORKFLOW_ERROR';
if(/MCP/i.test(message)) category='MCP_ERROR';
else if(/timeout/i.test(message)) category='TIMEOUT';
else if(/validation/i.test(message)) category='VALIDATION_ERROR';
else if(/expired/i.test(message)) category='PROPOSAL_EXPIRED';
else if(/unauthor|forbidden|permission/i.test(message)) category='AUTHORIZATION_ERROR';
else if(/stale|version|conflict/i.test(message)) category='VERSION_CONFLICT';
else if(/sqlite|database|storage/i.test(message)) category='STORAGE_ERROR';
else if(/model|openai|llm/i.test(message)) category='MODEL_ERROR';
return [{json:{occurred_at:new Date().toISOString(),workflow_id:w.id||null,workflow_name:w.name||null,execution_id:e.id||null,category,error_name:e.error?.name||null,safe_message:message.slice(0,500),note:'Prompt bodies, credentials, headers, and full model responses are intentionally omitted.'}}];
